interface State {
  handle(context: Context): void;
}

class Context {
  private state: State;
  constructor(state: State) { this.state = state; }
  setState(state: State) { this.state = state; }
  request() { this.state.handle(this); }
}

class ConcreteStateA implements State {
  handle(ctx: Context) { ctx.setState(new ConcreteStateB()); }
}

class ConcreteStateB implements State {
  handle(ctx: Context) { ctx.setState(new ConcreteStateA()); }
}

