/* Version A */
interface State { handle(ctx: OrderContext): void }
class PendingState implements State {
  handle(ctx: OrderContext) { ctx.setState(new PaidState()); }
}
class PaidState implements State {
  handle(ctx: OrderContext) { /* ship order */ }
}
class OrderContext {
  private state: State;
  constructor(s: State) { this.state = s; }
  transition() { this.state.handle(this); }
}

